```python
def get_float(prompt):
    """Prompts the user for a float and validates the input."""
    while True:
        try:
            num = float(input(prompt))
            return num
        except ValueError:
            print("That's not a valid number. Please try again.")

def get_operation():
    """Prompts the user for an operation and validates the input."""
    while True:
        operation = input("Enter the operation (+, -, *, /): ").strip()
        if operation in ['+', '-', '*', '/']:
            return operation
        else:
            print("That's not a valid operation. Please try again.")

def perform_operation(num1, num2, operation):
    """Performs the given operation on the two numbers and returns the result."""
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        try:
            return num1 / num2
        except ZeroDivisionError:
            print("Error: Division by zero is not allowed.")
            return None

def main():
    num1 = get_float("Enter the first number: ")
    operation = get_operation()
    num2 = get_float("Enter the second number: ")

    result = perform_operation(num1, num2, operation)

    if result is not None:
        print(f"{num1} {operation} {num2} = {result}")

if __name__ == "__main__":
    main()
```

This program will keep prompting the user for input until they enter a valid operation and two numbers. It will then perform the operation and display the result. If the user enters a division operation and tries to divide by zero, the program will display an error message and return `None`.
